files.content:
* {
  box-sizing: border-box;
  margin: 0;
}

.pages {
  min-height: 100vh;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.cards__list {
  gap: 25px;
  display: grid;
  padding: 50px;

  /* Сделайте элемент грид-контейнером с отступами 25px между элементами */
  list-style-type: none;
}

.card {
  border: 1px solid #000;
  padding: 50px;
  font-family: 'Open Sans', sans-serif;
  font-weight: 400;
  font-size: 32px;
  font-style: italic;
  line-height: 1.37;
  background-color: #fff;
  aspect-ratio: 1 / 1;
}
